5829	/// Modal screen changes. These map to the literal terminal
5830	/// modes to enable or disable alternate screen modes. They each
5831	/// have subtle behaviors so we define them as an enum here.
5832	pub const SwitchScreenMode = enum {
5833	    /// Legacy alternate screen mode. This goes to the alternate
5834	    /// screen or primary screen and only copies the cursor. The
5835	    /// screen is not erased.
5836	    @"47",
5837	
5838	    /// Alternate screen mode where the alternate screen is cleared
5839	    /// on exit. The primary screen is never cleared. The cursor is
5840	    /// copied.
5841	    @"1047",
5842	
5843	    /// Save primary screen cursor, switch to alternate screen,
5844	    /// and clear the alternate screen on entry. On exit,
