  1893	pub fn print(self: *Terminal, c: u21) !void {
  1894	    // log.debug("print={x} y={} x={}", .{ c, self.screens.active.cursor.y, self.screens.active.cursor.x });
  1895	
  1896	    // If we're not on the main display, do nothing for now
  1897	    if (self.status_display != .main) {
  1898	        @branchHint(.cold);
  1899	        return;
  1900	    }
  1901	
  1902	    // After doing any printing, wrapping, scrolling, etc. we want to ensure
  1903	    // that our screen remains in a consistent state.
  1904	    defer self.screens.active.assertIntegrity();
  1905	
  1906	    // The charset this character is printed with. A single shift applies to
  1907	    // exactly one character, so it is used up here, whether the character
  1908	    // takes a cell or attaches to the previous one: xterm clears it for a
  1909	    // combining character and so do we.
  1910	    const charset: charsets.Charset = charset: {
  1911	        const state = &self.screens.active.charset;
  1912	        const key = state.single_shift orelse state.gl;
  1913	        state.single_shift = null;
  1914	        break :charset state.charsets.get(key);
  1915	    };
  1916	
  1917	    // Our right margin depends where our cursor is now. A cursor right
  1918	    // of the right margin prints up to the screen edge. Every printWrap
  1919	    // below moves the cursor to the left margin, inside the margins, so
  1920	    // each one resets this to the right margin (as xterm's dotext does).
  1921	    var right_limit: usize = if (self.screens.active.cursor.x > self.scrolling_region.right)
  1922	        self.cols
  1923	    else
  1924	        self.scrolling_region.right + 1;
  1925	
  2200	    // only do insert mode if we're not at the end of the line.
  2201	    if (self.modes.get(.insert) and
  2202	        self.screens.active.cursor.x + width < self.cols)
  2203	    {
  2204	        self.insertBlanks(width);
  2205	    }
  2206	
  2207	    switch (width) {
  2208	        // Single cell is very easy: just write in the cell
  2209	        1 => {
  2210	            @branchHint(.likely);
  2211	            // writeCell marks the row dirty.
  2212	            @call(.always_inline, printCell, .{ self, c, .narrow, charset });
  2213	        },
  2214	
  2215	        // Wide character requires a spacer. We print this by
  2216	        // using two cells: the first is flagged "wide" and has the
  2217	        // wide char. The second is guaranteed to be a spacer if
  2218	        // we're not at the end of the line.
  2219	        2 => if ((right_limit - self.scrolling_region.left) > 1) {
  2220	            // If we don't have space for the wide char, we need
  2221	            // to insert spacers and wrap. Then we just print the wide
  2222	            // char as normal.
  2223	            if (self.screens.active.cursor.x == right_limit - 1) {
  2224	                // If we don't have wraparound enabled then we don't print
  2225	                // this character at all and don't move the cursor. This is
  2226	                // how xterm behaves.
  2227	                if (!self.modes.get(.wraparound)) return;
  2228	
  2229	                // We only create a spacer head if we're at the real edge
  2230	                // of the screen. Otherwise, we clear the space with a narrow.
  2231	                // This allows soft wrapping to work correctly.
  2232	                if (right_limit == self.cols) {
  2233	                    // Special-case: we need to set wrap to true even
  2234	                    // though we call printWrap below because if there is
  2235	                    // a page resize during printCell then it'll fail
  2236	                    // integrity checks.
  2237	                    self.screens.active.cursor.page_row.wrap = true;
  2238	                    self.writeCell(0, .spacer_head);
  2239	                } else {
  2240	                    self.writeCell(0, .narrow);
  2241	                }
  2242	                try self.printWrap();
  2243	                right_limit = self.scrolling_region.right + 1;
  2244	            }
  2245	
  2246	            self.printCell(c, .wide, charset);
