  2269	/// Prints the character unmapped_c into the cell under the cursor, mapped
  2270	/// through set, the charset print chose for it. Spacers and cells that
  2271	/// already hold a mapped character are written with writeCell instead.
  2272	fn printCell(
  2273	    self: *Terminal,
  2274	    unmapped_c: u21,
  2275	    wide: Cell.Wide,
  2276	    set: charsets.Charset,
  2277	) void {
  2278	    const c: u21 = c: {
  2279	        // TODO: non-utf8 handling, gr
  2280	
  2281	        // UTF-8 or ASCII is used as-is
  2282	        if (set == .utf8 or set == .ascii) {
  2283	            @branchHint(.likely);
  2284	            break :c unmapped_c;
  2285	        }
  2286	
  2287	        // The tables only cover 0x00-0xFF. Like xterm, which never remaps a
  2288	        // character above 255 in UTF-8 mode, we print anything above as is,
  2289	        // which also keeps it at the width it was measured with.
  2290	        if (unmapped_c > std.math.maxInt(u8)) break :c unmapped_c;
  2291	
  2292	        // Get our lookup table and map it
  2293	        const table = charsets.table(set);
  2294	        break :c @intCast(table[@intCast(unmapped_c)]);
  2295	    };
  2296	
  2297	    @call(.always_inline, writeCell, .{ self, c, wide });
  2298	}
