  2315	
  2316	    // If the wide property of this cell is the same, then we don't
  2317	    // need to do the special handling here because the structure will
  2318	    // be the same. If it is NOT the same, then we may need to clear some
  2319	    // cells.
  2320	    if (cell.wide != wide) {
  2321	        switch (cell.wide) {
  2322	            // Previous cell was narrow. Do nothing.
  2323	            .narrow => {},
  2324	
  2325	            // Previous cell was wide. We need to clear the tail and head.
  2326	            .wide => wide: {
  2327	                if (self.screens.active.cursor.x >= self.cols - 1) break :wide;
  2328	
  2329	                const spacer_cell = self.screens.active.cursorCellRight(1);
  2330	                self.screens.active.clearCells(
  2331	                    self.screens.active.cursor.page_pin.node.page(),
  2332	                    self.screens.active.cursor.page_row,
  2333	                    spacer_cell[0..1],
  2334	                );
