  2970	// Same as horizontalTab but moves to the previous tabstop instead of the next.
  2971	pub fn horizontalTabBack(self: *Terminal) void {
  2972	    // With origin mode enabled, our leftmost limit is the left margin.
  2973	    const left_limit = if (self.modes.get(.origin)) self.scrolling_region.left else 0;
  2974	
  2975	    while (true) {
  2976	        // If we're already at the edge of the screen, then we're done.
  2977	        if (self.screens.active.cursor.x <= left_limit) return;
  2978	
  2979	        // Move the cursor left
  2980	        self.screens.active.cursorLeft(1);
  2981	        if (self.tabstops.get(self.screens.active.cursor.x)) return;
  2982	    }
  2983	}
