7385	/// Returns the bottom right of the screen for the given tag. This can
7386	/// return null because it is possible that a tag is not in the screen
7387	/// (e.g. history does not yet exist).
7388	pub fn getBottomRight(self: *const PageList, tag: point.Tag) ?Pin {
7389	    return switch (tag) {
7390	        .screen, .active => last: {
7391	            const node = self.pages.last.?;
7392	            break :last .{
7393	                .node = node,
7394	                .y = node.rows() - 1,
7395	                .x = node.cols() - 1,
7396	            };
7397	        },
7398	
7399	        .viewport => viewport: {
7400	            var br = self.getTopLeft(.viewport);
7401	            br = br.down(self.rows - 1).?;
7402	            br.x = br.node.cols() - 1;
7403	            break :viewport br;
7404	        },
7405	
7406	        .history => active: {
7407	            var br = self.getTopLeft(.active);
7408	            br = br.up(1) orelse return null;
7409	            br.x = br.node.cols() - 1;
7410	            break :active br;
7411	        },
7412	    };
7413	}
