  2336	                // If we're near the left edge, a wide char may have
  2337	                // wrapped from the previous row, leaving a spacer_head
  2338	                // at the end of that row. Clear it so the previous row
  2339	                // doesn't keep a stale spacer_head.
  2340	                if (self.screens.active.cursor.y > 0 and self.screens.active.cursor.x <= 1) {
  2341	                    const head_cell = self.screens.active.cursorCellEndOfPrev();
  2342	                    if (head_cell.wide == .spacer_head) head_cell.wide = .narrow;
  2343	                }
  2344	            },
  2345	
  2346	            .spacer_tail => {
  2347	                assert(self.screens.active.cursor.x > 0);
  2348	
  2349	                // So integrity checks pass. We fix this up later so we don't
  2350	                // need to do this without safety checks.
  2351	                if (comptime build_options.slow_runtime_safety) {
  2352	                    cell.wide = .narrow;
  2353	                }
  2354	
  2355	                const wide_cell = self.screens.active.cursorCellLeft(1);
  2356	                self.screens.active.clearCells(
  2357	                    self.screens.active.cursor.page_pin.node.page(),
  2358	                    self.screens.active.cursor.page_row,
  2359	                    wide_cell[0..1],
  2360	                );
