  2362	                // wrapped from the previous row, leaving a spacer_head
  2363	                // at the end of that row. Clear it so the previous row
  2364	                // doesn't keep a stale spacer_head.
  2365	                if (self.screens.active.cursor.y > 0 and self.screens.active.cursor.x <= 1) {
