  2956	/// Horizontal tab moves the cursor to the next tabstop, clearing
  2957	/// the screen to the left the tabstop.
  2958	pub fn horizontalTab(self: *Terminal) void {
  2959	    while (self.screens.active.cursor.x < self.scrolling_region.right) {
  2960	        // Move the cursor right
  2961	        self.screens.active.cursorRight(1);
  2962	
  2963	        // If the last cursor position was a tabstop we return. We do
  2964	        // "last cursor position" because we want a space to be written
  2965	        // at the tabstop unless we're at the end (the while condition).
  2966	        if (self.tabstops.get(self.screens.active.cursor.x)) return;
  2967	    }
  2968	}
