  3234	/// row.
  3235	pub fn setCursorPos(self: *Terminal, row_req: usize, col_req: usize) void {
  3236	    // If cursor origin mode is set the cursor row will be moved relative to
  3237	    // the top margin row and adjusted to be above or at bottom-most row in
  3238	    // the current scroll region.
  3239	    //
  3240	    // If origin mode is set and left and right margin mode is set the cursor
  3241	    // will be moved relative to the left margin column and adjusted to be on
  3242	    // or left of the right margin column.
  3243	    const params: struct {
  3244	        x_offset: size.CellCountInt = 0,
  3245	        y_offset: size.CellCountInt = 0,
  3246	        x_max: size.CellCountInt,
  3247	        y_max: size.CellCountInt,
  3248	    } = if (self.modes.get(.origin)) .{
  3249	        .x_offset = self.scrolling_region.left,
  3250	        .y_offset = self.scrolling_region.top,
  3251	        .x_max = self.scrolling_region.right + 1, // We need this 1-indexed
  3252	        .y_max = self.scrolling_region.bottom + 1, // We need this 1-indexed
  3253	    } else .{
  3254	        .x_max = self.cols,
  3255	        .y_max = self.rows,
  3256	    };
