  4275	pub fn eraseChars(self: *Terminal, count_req: usize) void {
  4276	    const count = end: {
  4277	        const remaining = self.cols - self.screens.active.cursor.x;
  4278	        var end = @min(remaining, @max(count_req, 1));
  4279	
  4280	        // If our last cell is a wide char then we need to also clear the
  4281	        // cell beyond it since we can't just split a wide char.
  4282	        if (end != remaining) {
  4283	            const last = self.screens.active.cursorCellRight(end - 1);
  4284	            if (last.wide == .wide) end += 1;
  4285	        }
  4286	
  4287	        break :end end;
  4288	    };
