  4290	    // Handle any boundary conditions on the edges of the erased area.
  4291	    //
  4292	    // TODO(qwerasd): This isn't actually correct if you take in to account
  4293	    // protected modes. We need to figure out how to make `clearCells` or at
  4294	    // least `clearUnprotectedCells` handle boundary conditions...
  4295	    self.screens.active.splitCellBoundary(self.screens.active.cursor.x);
  4296	    self.screens.active.splitCellBoundary(self.screens.active.cursor.x + count);
