  4303	
  4304	    // Clear the cells
  4305	    const cells: [*]Cell = @ptrCast(self.screens.active.cursor.page_cell);
  4306	
  4307	    // If we never had a protection mode, then we can assume no cells
  4308	    // are protected and go with the fast path. If the last protection
  4309	    // mode was not ISO we also always ignore protection attributes.
  4310	    if (self.screens.active.protected_mode != .iso) {
  4311	        self.screens.active.clearCells(
  4312	            self.screens.active.cursor.page_pin.node.page(),
  4313	            self.screens.active.cursor.page_row,
  4314	            cells[0..count],
  4315	        );
  4316	        return;
  4317	    }
  4318	
  4319	    self.screens.active.clearUnprotectedCells(
  4320	        self.screens.active.cursor.page_pin.node.page(),
  4321	        self.screens.active.cursor.page_row,
  4322	        cells[0..count],
  4323	    );
